"""SHA-gated independent Beamo / BeamoDecal construction and bake branches."""
import json,pathlib,struct,sys
from native import Native
root=pathlib.Path(__file__).resolve().parent.parent;n=Native(sys.argv[1])
functions={'Beamo.placement':0x100198cf0,'BeamoDecal.placement':0x100199280,'Barn.Initialize':0x100194a10,'Barn.CreateBeamo':0x1001973a0,'Barn.CreateBeamoDecal':0x1001974a0,'Beamo.Changed':0x100194940,'BeamoDecal.Changed':0x1001949b0,'Beamo.SetTransform':0x100194960,'BeamoDecal.SetTransform':0x1001949c0,'Beamo.GetTransform':0x1001985b0,'BeamoDecal.GetTransform':0x100198730,'Barn.Load':0x100195050,'Barn.Unload':0x100194a90,'Beamo.destructor':0x100198510,'BeamoDecal.destructor':0x100198690,
 'uploadLod':0x100197ab0,'normals':0x10045ee30,'normalGenerator':0x10045edf0,'secondaryWeights':0x1001975c0,'distanceToObb':0x10078ce10,'defaultLightColor':0x10077d310,'defaultLightEncoding':0x100414530,'mapBuffer':0x1007950d0,'VertexData.stream':0x1007f5430,'VertexData.indices':0x1007f55d0}
for name,address in functions.items():
 assert n.bounds(address)[0]==address
 (root/'evidence'/('beamo-'+name+'.asm')).write_text(n.annotated(address))
assert n.read(0x100aa70e4,4)==bytes(4)
assert n.read(0x100aabf60,8)==struct.pack('<2f',-1,-1)
world=struct.unpack('<Q',n.read(0x100c0d670,8))[0]+16
report={'executableSha256':n.digest,'functions':{k:hex(v) for k,v in functions.items()},'worldVptr':hex(world),'beamoVptr':'0x100c126d0','decalVptr':'0x100c12758','barn':{'beamoPool':16,'beamoStride':192,'beamoLimit':512,'decalPool':0x18010,'decalStride':128,'decalLimit':256,'beamoCount':0x20010,'decalCount':0x20014,'loadedCount':0x20018,'runtimeTable':0x20020,'runtimeStride':384},'sharedConsumer':{'normalBranch':'0x1001951e5..0x100195290','decalBranch':'0x100195290..0x100195318','bakeSelection':'0x100195427..0x100195678','loadedLodStride':24,'checkedPointer':16,'ordinaryLightPointer':8,'lodDistance':'Mesh v28 first float / native Mesh LOD +0','lodEnable':'zero disables, unordered/nonzero enables','decalSelection':'first two available LODs; independent from Beamo saved enables','thirdLod':'checked later in upload, not by this acceptance block','recordPreparation':'0x1001950da..0x100195330; original material GUID lookup; primary Beamo may be null, secondary and Decal primary assert','decalDisableDistance':'positive retained; zero/negative/NaN -> float32 max 0x7f7fffff','decalDisableDistanceConstant':'0x100aa78b8'},'scope':'Whole normal placement/Create/Initialize/Changed/SetTransform/GetTransform and resolved-resource bake-selection subchain implemented. Raw tags are separate evidence. Barn.Load first record pass and whole Barn.Unload control flow plus normal non-deleting destructors are implemented with explicit metadata/VertexData/Renderable/CollisionGeo/string/virtual-destructor services. Full Barn.Load/upload/stream allocation/collision/skirts/visibility and dependent lifecycle implementations remain open; whole class acceptance is zero.'}
report['upload']={'barnSegment':'0x100195be7..0x100195f45','allMeshLods':True,'lodRangeOffset':0xfc,'lodCountOffset':0x13c,'lodRangeStride':16,'vertexStride':48,'materialAlphaBoundary':'sum of three alpha bytes > 674: secondary; 1..674: primary plus alpha; 0: primary','culledByte':'nonzero skips triangle; compact live vertex map','normalCapability':'RSQRTSS requires explicit independently checked input/output capability','streamFormats':[3,28,24,32,32,28,28,28],'streamAttributes':[1,2,3,5,6,13,14,15]}
report['scope']='Normal placements/pool/record/bake/unload subchains, whole normal upload-LOD/normals/weights/Barn stream scheduler, bounds/sphere/distance/collision descriptor/instance writeback and material group indexing are implemented. CollisionGeo.Remove pool control flow is restored. Scratch heap/RSQRTSS/powf, metadata/resource/VertexData, collision registration/index and string services remain explicit; complete ResourceRef loading, material shader/RenderList/Renderable drawing, Visibility/skirts/lifecycle and whole-class acceptance remain open.'
(root/'docs'/'beamo-native.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
